import re
import sys

LINE_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$"
)


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\r\n"))
            if m:
                time, module, message = m.groups()
                rows.append({"time": time, "module": module, "message": message})
    return rows


def format_table(rows):
    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        cells = [c.replace("|", "\\|") for c in (r["time"], r["module"], r["message"])]
        lines.append("| " + " | ".join(cells) + " |")
    return "\n".join(lines)


def main(argv):
    path = argv[1] if len(argv) > 1 else "sample.log"
    print(format_table(parse_errors(path)))


if __name__ == "__main__":
    main(sys.argv)
